package com.betterobjecthider;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(BetterObjectHiderPlugin.CONFIG_GROUP)
public interface BetterObjectHiderConfig extends Config
{
	@ConfigItem(
		position = 0,
		keyName = "requireShift",
		name = "Require Shift for menu options",
		description = "Only show Hide/Unhide options while holding Shift, keeping normal right-click menus clean"
	)
	default boolean requireShift()
	{
		return true;
	}

	@ConfigItem(
		position = 1,
		keyName = "revealAll",
		name = "Reveal hidden objects",
		description = "Temporarily show all hidden objects so you can right-click them to unhide"
	)
	default boolean revealAll()
	{
		return false;
	}

	@ConfigItem(
		position = 2,
		keyName = "menuReach",
		name = "Hide menu options",
		description = "Which hide reaches the right-click menu offers. Trims menu clutter only — "
			+ "existing hides keep working and Unhide options always appear."
	)
	default MenuReach menuReach()
	{
		return MenuReach.ALL;
	}

	@ConfigItem(
		position = 3,
		keyName = "chatFeedback",
		name = "Confirm hides in chat",
		description = "Print a game-chat confirmation whenever you hide an object"
	)
	default boolean chatFeedback()
	{
		return true;
	}

	@ConfigItem(
		position = 4,
		keyName = "showHelp",
		name = "Show usage help",
		description = "Show the short how-to box at the top of the side panel"
	)
	default boolean showHelp()
	{
		return true;
	}

	@Range(max = 10080)
	@Units(Units.MINUTES)
	@ConfigItem(
		position = 5,
		keyName = "activeGroupTimeoutMinutes",
		name = "Active group timeout",
		description = "If the active group hasn't been used for this long, new hides go back to the Default group "
			+ "(prevents forgotten selections from collecting stray hides). The timer refreshes every time you "
			+ "hide something or pick an active group. 0 = never reset."
	)
	default int activeGroupTimeoutMinutes()
	{
		return 60;
	}

	// Name-based schema (v3). The old "groups" key held an ID-based format and is
	// intentionally not read — a fresh install/schema, nothing shipped on the old one.
	@ConfigItem(
		keyName = "groupsV2",
		name = "",
		description = "",
		hidden = true
	)
	default String groups()
	{
		return "";
	}

	@ConfigItem(
		keyName = "activeGroup",
		name = "",
		description = "",
		hidden = true
	)
	default String activeGroup()
	{
		return "";
	}
}

/*
 * Copyright (c) 2026, Jack Hartnett
 * All rights reserved.
 *
 * BSD-2-Clause. See LICENSE.
 *
 * Inspired by LuxOG's custom-object-hider (BSD-2-Clause).
 * This plugin is purely cosmetic: it changes only what is rendered
 * client-side. It sends nothing to the server and automates nothing.
 *
 * Objects are hidden by their in-game NAME plus a map location — never by
 * object ID. You point at a named object you can see and hide that object at
 * that spot; objects with no name cannot be hidden. No IDs are entered,
 * stored, or targeted.
 */
package com.betterobjecthider;

import com.betterobjecthider.ui.BetterObjectHiderPanel;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Constants;
